/* Fundamentals terminal. Headlines and data are served through the public-data Pages Function. */
let newsBookmarks=[], terminalQuery='',terminalMarket='',terminalTag='',terminalSource='',terminalSaved=false,terminalPaused=false,terminalArticle=null,cotMarket='gold',cotRange=52;
const terminalCache=new Map(),terminalRequests=new Map(),terminalDrafts=new Map();
const TERMINAL_VIEWS=[['dashboard','◈','Dashboard'],['live','≋','Live News'],['calendar','▦','Economic Calendar'],['politics','⚡','Politics & Tariffs'],['cot','▥','COT Report'],['fed','◎','Fed Watch'],['cpi','◉','USA CPI'],['nfp','▥','USA NFP'],['events','★','My Events']];
function terminalTime(iso){return iso?new Date(iso).toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}):'—';}
function terminalDate(iso){return iso?new Date(iso).toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',year:'numeric'}):'—';}
function terminalNumber(n){return n===null||n===undefined?'—':Number(n).toLocaleString('en-IN',{maximumFractionDigits:0});}
function signedNumber(n){return n===null||n===undefined?'—':(n>0?'+':'')+terminalNumber(n);}
function terminalApi(kind,market){return '/api/terminal?kind='+kind+(market?'&market='+encodeURIComponent(market):'');}
async function terminalFetch(kind,market,force=false){
 const key=kind+(market?':'+market:'');if(terminalRequests.has(key))return terminalRequests.get(key);
 const current=terminalCache.get(key);if(!force&&current&&Date.now()-current.received<(['cot','cpi','nfp'].includes(kind)?3600000:60000))return current.data;
 const request=(async()=>{try{const response=await fetch(terminalApi(kind,market),{signal:AbortSignal.timeout(30000)});const data=await response.json();if(!response.ok)throw Error(data.error||'The source is temporarily unavailable.');terminalCache.set(key,{data,received:Date.now(),error:''});return data;}catch(e){terminalCache.set(key,{...current,error:e.message,received:current?.received||0});return current?.data||null;}finally{terminalRequests.delete(key);}})();terminalRequests.set(key,request);return request;
}
function terminalError(kind){const entry=terminalCache.get(kind);return entry?.error?'<div class="terminal-notice">'+hx(entry.data?'Showing the last successful update. ':'')+hx(entry.error)+' <button class="btn ghost" onclick="refreshNewsTerminal(true)">Retry</button></div>':'';}
function terminalPanel(title,body,extra=''){return '<article class="terminal-panel '+extra+'"><div class="terminal-panel-head">'+hx(title)+'</div>'+body+'</article>';}
function renderNews(){
 const host=document.getElementById('news');if(!host)return;
 host.innerHTML=`<div class="terminal-header"><div><div class="terminal-eyebrow">MARKET INTELLIGENCE / FUNDAMENTALS</div><h2>Fundamentals</h2><p class="feature-summary">The releases, headlines and positioning behind the move.</p></div><div class="terminal-session"><span class="terminal-live-dot"></span><span id="terminalStatus">${terminalPaused?'Updates paused':'Feeds checked every 60s'}</span><button class="btn ghost" id="terminalRefresh" aria-label="Refresh market data">↻ Refresh</button></div></div><nav class="terminal-nav" aria-label="News terminal views">${TERMINAL_VIEWS.map(([id,icon,label])=>'<button class="'+(newsView===id?'selected':'')+'" data-terminal-view="'+id+'"><span>'+icon+'</span> '+label+'</button>').join('')}</nav><div id="newsMain"></div><div class="terminal-footer">ALPHA TERMINAL <span>Source timestamps shown · All display times IST · Feeds may be delayed</span></div>`;
 host.querySelectorAll('[data-terminal-view]').forEach(b=>b.onclick=()=>{newsView=b.dataset.terminalView;terminalArticle=null;renderNews();});document.getElementById('terminalRefresh').onclick=()=>refreshNewsTerminal(true);
 renderNewsBody();refreshNewsTerminal();
}
function renderNewsBody(){
 const main=document.getElementById('newsMain');if(!main)return;
 if(newsView==='events'){main.innerHTML='<div class="feature-toolbar"><h3 style="flex:1">My important events</h3><button class="btn" onclick="editNewsEvent()">+ Add event</button></div>';const panel=document.createElement('div');panel.id='eventPlanner';main.append(panel);renderSavedEvents();return;}
 if(newsView==='calendar'){renderTerminalCalendar(main);return;}
 if(newsView==='dashboard'){renderTerminalDashboard(main);return;}
 if(newsView==='live'||newsView==='politics'){renderTerminalHeadlines(main);return;}
 if(newsView==='cot'){renderTerminalCot(main);return;}
 if(newsView==='cpi'||newsView==='nfp'){renderTerminalMacro(main,newsView);return;}
 if(newsView==='fed')renderTerminalFed(main);
}
async function refreshNewsTerminal(force=false){
 const view=newsView,active=document.getElementById('news')?.classList.contains('active');
 if(!active&&!force)return;
 const needed=view==='dashboard'?[terminalFetch('headlines',null,force),terminalFetch('fed',null,force),terminalFetch('cot',null,force),terminalFetch('cpi',null,force),terminalFetch('nfp',null,force),terminalFetch('calendar',null,force)]:view==='live'||view==='politics'?[terminalFetch('headlines',null,force)]:view==='cot'?[terminalFetch('cot',null,force),terminalFetch('cot',cotMarket,force)]:view==='calendar'?[terminalFetch('calendar',null,force)]:view==='fed'?[terminalFetch('fed',null,force)]:['cpi','nfp'].includes(view)?[terminalFetch(view,null,force),terminalFetch('headlines',null,force)]:[];
 if(!needed.length)return;
 const button=document.getElementById('terminalRefresh');if(button)button.disabled=true;
 await Promise.allSettled(needed);if(button)button.disabled=false;if(newsView!==view)return;
 const focus=document.activeElement?.id,start=document.activeElement?.selectionStart;
 renderNewsBody();if(focus&&document.getElementById(focus)){const el=document.getElementById(focus);el.focus();if(start!==null&&typeof el.setSelectionRange==='function')try{el.setSelectionRange(start,start);}catch{}}
 const status=document.getElementById('terminalStatus');if(status)status.textContent=terminalPaused?'Updates paused':'Checked '+terminalTime(new Date().toISOString())+' IST';
}
function terminalFeedHealth(){const entry=terminalCache.get('headlines');return (entry?.data?.sources||[]).map(s=>'<span class="terminal-source '+(s.ok?'':'unavailable')+'">'+(s.ok?'●':'○')+' '+hx(s.name)+(s.ok?'':' · unavailable')+'</span>').join('');}
function terminalEmpty(key,message='Connecting to data sources…'){return terminalError(key)+'<div class="feature-empty">'+hx(terminalCache.has(key)?'Data unavailable. Use Refresh to try again.':message)+'</div>';}
function dashboardHighImpactEvents(now=Date.now()){
 const rows=(terminalCache.get('calendar')?.data?.items||[]).filter(e=>e.impact==='High'&&Date.parse(e.date)>now).map(e=>({...e,kind:'calendar'}));
 for(const kind of ['cpi','nfp'])for(const r of terminalCache.get(kind)?.data?.schedule||[]){if(Date.parse(r.date)<=now)continue;if(!rows.some(e=>e.currency==='USD'&&Math.abs(Date.parse(e.date)-Date.parse(r.date))<60000&&new RegExp(kind==='cpi'?'cpi|consumer price':'non.?farm|employment change','i').test(e.title)))rows.push({...r,currency:'USD',impact:'High',kind,forecast:null,previous:null});}
 return rows.sort((a,b)=>Date.parse(a.date)-Date.parse(b.date));
}
function dashboardEventRow(e){return '<div class="dash-event-row"><time>'+terminalDate(e.date)+'<strong>'+terminalTime(e.date)+' IST</strong></time><span>'+econFlag(e.currency)+' '+hx(e.currency)+'</span><div><strong>'+hx(e.title)+'</strong><small>Forecast '+hx(e.forecast??'—')+' · Previous '+hx(e.previous??'—')+'</small></div><span class="news-impact high">HIGH</span></div>';}
const DASH_MARKETS=[['Gold','OANDA:XAUUSD','🟡'],['Silver','OANDA:XAGUSD','⚪'],['EUR/USD','OANDA:EURUSD','🇪🇺🇺🇸'],['GBP/USD','OANDA:GBPUSD','🇬🇧🇺🇸'],['USD/JPY','OANDA:USDJPY','🇺🇸🇯🇵'],['AUD/USD','OANDA:AUDUSD','🇦🇺🇺🇸'],['USD/CAD','OANDA:USDCAD','🇺🇸🇨🇦'],['USD/CHF','OANDA:USDCHF','🇺🇸🇨🇭'],['NZD/USD','OANDA:NZDUSD','🇳🇿🇺🇸'],['GBP/JPY','OANDA:GBPJPY','🇬🇧🇯🇵'],['Bitcoin','BITSTAMP:BTCUSD','₿'],['Ether','BITSTAMP:ETHUSD','◆']];
function dashboardMarketTiles(){return '<div class="market-tile-grid">'+DASH_MARKETS.map(([name,symbol,icon])=>'<div class="market-tile"><div>'+icon+' '+name+'</div><tv-ticker-tag preserve-text symbol="'+symbol+'" theme="'+currentTvTheme()+'" transparent>'+name+'</tv-ticker-tag></div>').join('')+'</div><p class="feature-summary" style="padding:0 16px 16px">Daily changes by TradingView · Provider session baseline, which may differ from 00:00 UTC. Hover a market for details. <a href="https://www.tradingview.com/markets/" target="_blank" rel="noopener">TradingView ↗</a></p>';}
function loadDashboardTileProvider(){if(document.getElementById('tvTickerTagModule'))return;const script=document.createElement('script');script.id='tvTickerTagModule';script.type='module';script.src='https://widgets.tradingview-widget.com/w/en/tv-ticker-tag.js';document.head.append(script);}
function dashboardPriorityHeadlines(items){return items.filter(a=>/\bfomc\b|\bfed\b|\bcpi\b|\bnfp\b|payroll|rate (decision|hike|cut)|central bank|tariff|missile|airstrike|war\b|inflation|employment report/i.test(a.title)).slice(0,6);}
function renderTerminalDashboard(main){
 const headlines=terminalCache.get('headlines')?.data,fed=terminalCache.get('fed')?.data,cot=terminalCache.get('cot')?.data,rate=fed?.rate,nextFed=fed?.meetings?.[0],events=dashboardHighImpactEvents(),next=events[0],today=econDateKey(new Date()),calendar=terminalCache.get('calendar')?.data,calendarRows=(calendar?.items||[]).filter(e=>econDateKey(e.date)===today&&e.impact==='High'),sessions=terminalSessions(),priority=dashboardPriorityHeadlines(headlines?.items||[]),positionRows=(cot?.markets||[]).filter(m=>Number.isFinite(m.long)&&Number.isFinite(m.short));
 const nextCard=next?'<div class="macro-card next-release-card"><span class="news-impact high">HIGH IMPACT · '+econFlag(next.currency)+' '+hx(next.currency)+'</span><h3>'+hx(next.title)+'</h3><p>'+terminalDate(next.date)+' · '+terminalTime(next.date)+' IST</p><strong class="release-countdown" data-countdown="'+hx(next.date)+'">'+countdownLabel(next.date)+'</strong><div class="release-values"><div><small>FORECAST</small><strong>'+hx(next.forecast??'—')+'</strong></div><div><small>PREVIOUS</small><strong>'+hx(next.previous??'—')+'</strong></div></div><button class="terminal-text-button" data-go="'+next.kind+'">On the calendar →</button></div>':'<div class="feature-empty">'+(terminalCache.has('calendar')?'No upcoming high-impact releases available.':'Loading high-impact releases…')+' '+terminalError('calendar')+'</div>';
 main.innerHTML='<div class="terminal-desk-banner"><div><div class="terminal-eyebrow">LIVE DESK · '+terminalDate(new Date().toISOString())+'</div><h3>'+hx(sessions.filter(s=>s.open).map(s=>s.name).join(' & ')||'Global markets')+' · your market briefing.</h3></div><div class="terminal-session-clocks">'+sessions.map(s=>'<div><span>'+s.name+'</span><strong>'+s.time+'</strong><small class="'+(s.open?'session-open':'')+'">'+(s.open?'OPEN':'CLOSED')+'</small></div>').join('')+'</div></div><div class="dash-top-grid">'+terminalPanel('NEXT RELEASE · HIGH IMPACT ONLY',nextCard)+terminalPanel('SESSION CLOCK · 24 HOURS IST','<div id="sessionTimeline">'+sessionTimeline()+'</div>')+'</div><div class="terminal-kpis">'+terminalKpi('POLICY TARGET',rate?rate.targetRateFrom.toFixed(2)+'–'+rate.targetRateTo.toFixed(2)+'%':'—',rate?'NY Fed · '+terminalDate(rate.effectiveDate):'Rate feed unavailable')+terminalKpi('NEXT FED DECISION',nextFed?terminalDate(nextFed.date):'—',nextFed?countdownLabel(nextFed.date):'Pricing unavailable')+terminalKpi('HIGH IMPACT · TODAY',calendar?String(calendarRows.length):'—','Provider-rated events · IST')+terminalKpi('UPCOMING · HIGH IMPACT',String(events.length),'Weekly feed + CPI/NFP schedules')+'</div><div class="dashboard-main-grid"><div>'+terminalPanel('TODAY · HIGH-IMPACT RELEASES',calendarRows.length?calendarRows.map(dashboardEventRow).join('')+'<button class="terminal-text-button" data-go="calendar">Full economic calendar →</button>':'<div class="feature-empty">No high-impact releases in today’s available feed.<button class="terminal-text-button" data-go="calendar">Open full calendar →</button></div>')+terminalPanel('MARKET-MOVING NEWS · MACRO & GEOPOLITICS','<div class="terminal-feed-health">'+terminalFeedHealth()+'</div><p class="feature-summary" style="padding:12px 18px">Headline keyword selection; publishers do not supply impact ratings.</p>'+terminalError('headlines')+(priority.length?priority.map(a=>headlineRow(a,true)).join(''):'<div class="feature-empty">No matching headlines in the current feeds.</div>'))+terminalPanel('LATEST MARKET HEADLINES',(headlines?.items||[]).slice(0,7).map(a=>headlineRow(a,true)).join('')+'<button class="terminal-text-button" data-go="live">Open live news →</button>')+'</div><aside>'+terminalPanel('MARKET HEATMAP · DAILY CHANGE',dashboardMarketTiles())+terminalPanel('FED WATCH',nextFed?'<div class="macro-card">'+fedOddsBars(nextFed)+'<button class="terminal-text-button" data-go="fed">Full Fed Watch →</button></div>':terminalEmpty('fed'))+terminalPanel('OTHER UPCOMING · HIGH IMPACT',events.slice(1,7).map(dashboardEventRow).join('')||'<div class="feature-empty">No further releases available.</div>')+terminalPanel('COT · SPECULATORS','<div class="macro-card">'+positionRows.slice(0,7).map(m=>{const total=m.long+m.short,pct=total?100*m.long/total:0;return '<div class="cot-mini-row"><span>'+hx(m.name)+'</span><strong>'+pct.toFixed(0)+'% long</strong><div class="cot-mini-bar"><i style="width:'+pct+'%"></i></div><small>'+terminalDate(m.date)+'</small></div>';}).join('')+'<button class="terminal-text-button" data-go="cot">COT report →</button></div>')+'</aside></div><p class="feature-summary">High-impact labels come from the calendar provider. CPI/NFP schedule fallbacks retain their verified dates; the calendar feed omits most released actuals.</p>';
 loadDashboardTileProvider();main.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{newsView=b.dataset.go;renderNews();});bindHeadlineRows(main);
}

function terminalKpi(label,value,detail){return '<div class="terminal-kpi"><span>'+hx(label)+'</span><strong>'+hx(value)+'</strong><small>'+hx(detail)+'</small></div>';}
function countdownLabel(date){const ms=Date.parse(date)-Date.now();if(ms<=0)return'Release time reached';return Math.floor(ms/86400000)+'d '+Math.floor(ms/3600000)%24+'h '+Math.floor(ms/60000)%60+'m';}
function headlineRow(a,compact=false){
 const saved=newsBookmarks.some(b=>b.url===a.url);return `<article class="terminal-headline ${compact?'compact':''} ${terminalArticle===a.id?'active':''}" data-article="${hx(a.id)}"><time>${terminalTime(a.published)}<small>${terminalDate(a.published)}</small></time><div><div class="terminal-headline-meta">${hx(a.source)} ${a.tags.map(t=>'<span>'+hx(t)+'</span>').join('')}</div><button class="terminal-headline-title" data-open-article>${hx(a.title)}</button></div><button class="terminal-bookmark" aria-label="${saved?'Unsave':'Save'} headline" data-bookmark>${saved?'★':'☆'}</button></article>`;
}
function filteredHeadlines(){let items=terminalSaved?newsBookmarks:terminalCache.get('headlines')?.data?.items||[];return items.filter(a=>(newsView!=='politics'||a.tags.includes('Politics'))&&(!terminalMarket||a.market===terminalMarket||(terminalMarket==='Equity'&&a.tags.includes('Equity'))||(terminalMarket==='Indian Market'&&a.tags.includes('India')))&&(!terminalTag||a.tags.includes(terminalTag))&&(!terminalSource||a.sourceId===terminalSource)&&[a.title,...a.tags].join(' ').toLowerCase().includes(terminalQuery.toLowerCase()));}
function renderTerminalHeadlines(main){
 main.innerHTML=`<div class="terminal-view-heading"><div><h3>${newsView==='politics'?'Politics & Tariffs':'Live News'}</h3><p class="feature-summary">${newsView==='politics'?'Headlines tagged for politics, tariffs and the White House.':'A chronological feed of market headlines. Open a headline to inspect its source and save notes.'}</p></div><button class="btn ghost" id="pauseNews">${terminalPaused?'▶ Resume updates':'Ⅱ Pause updates'}</button></div><div class="terminal-feed-health">${terminalFeedHealth()}</div>${terminalError('headlines')}<div class="feature-toolbar"><input id="terminalQuery" aria-label="Search headlines" placeholder="Search symbol, event or headline…" value="${hx(terminalQuery)}"><select id="terminalMarket" aria-label="Headline market"><option value="">All markets</option>${newsOptions(['Forex','Equity','Indian Market','Global'],terminalMarket)}</select><select id="terminalTag" aria-label="Headline topic"><option value="">All topics</option>${newsOptions(['Fed','Inflation','Jobs','Gold','Oil','USD','India','Equity','Politics'],terminalTag)}</select><select id="terminalSource" aria-label="Headline source"><option value="">All sources</option>${(terminalCache.get('headlines')?.data?.sources||[]).map(s=>'<option value="'+s.id+'" '+(s.id===terminalSource?'selected':'')+'>'+hx(s.name)+'</option>').join('')}</select><label class="feature-summary"><input type="checkbox" id="terminalSaved" ${terminalSaved?'checked':''}> Saved only</label></div><div class="terminal-live-layout"><div class="terminal-panel" id="headlineStream"></div><aside id="headlineDetail" class="terminal-panel terminal-detail"></aside></div><p class="feature-summary">Publisher RSS headlines · Delivery may be delayed · Automatic checks every 60 seconds. Topic tags use headline keywords.</p>`;
 document.getElementById('pauseNews').onclick=()=>{terminalPaused=!terminalPaused;renderNews();};
 for(const [id,set] of [['terminalQuery',v=>terminalQuery=v],['terminalMarket',v=>terminalMarket=v],['terminalTag',v=>terminalTag=v],['terminalSource',v=>terminalSource=v]]){const el=document.getElementById(id);el.value={terminalQuery,terminalMarket,terminalTag,terminalSource}[id];el.addEventListener(id==='terminalQuery'?'input':'change',()=>{set(el.value);renderHeadlineStream();});}
 document.getElementById('terminalSaved').onchange=e=>{terminalSaved=e.target.checked;renderHeadlineStream();};renderHeadlineStream();
}
function renderHeadlineStream(){const host=document.getElementById('headlineStream');if(!host)return;const items=filteredHeadlines();host.innerHTML=items.length?items.map(a=>headlineRow(a)).join(''):'<div class="feature-empty">'+(terminalCache.has('headlines')?'No headlines match these filters.':'Loading headline feeds…')+'</div>';bindHeadlineRows(host);renderHeadlineDetail();}
function articleById(id){return newsBookmarks.find(a=>a.id===id)||terminalCache.get('headlines')?.data?.items.find(a=>a.id===id);}
function bindHeadlineRows(host){host.querySelectorAll('[data-article]').forEach(row=>{const article=articleById(row.dataset.article);row.querySelector('[data-open-article]').onclick=()=>{terminalArticle=article.id;if(!['live','politics'].includes(newsView)){newsView='live';renderNews();}else{renderHeadlineStream();}};row.querySelector('[data-bookmark]').onclick=async()=>{await saveHeadline(article);if(!['live','politics'].includes(newsView))renderNewsBody();else renderHeadlineStream();};});}
async function saveHeadline(article,notes){
 try{let next=structuredClone(newsBookmarks),old=next.find(a=>a.url===article.url);if(notes!==undefined){if(old)old.notes=notes;else next.unshift({...article,notes,savedAt:new Date().toISOString()});}else if(old)next=next.filter(a=>a.url!==article.url);else next.unshift({...article,notes:'',savedAt:new Date().toISOString()});await sSet('news_bookmarks',next);newsBookmarks=next;}catch(e){alert('Could not save this headline: '+e.message);}
}
function renderHeadlineDetail(){
 const host=document.getElementById('headlineDetail');if(!host)return;const a=articleById(terminalArticle);if(!a){host.innerHTML='<div class="terminal-panel-head">READING DESK</div><div class="feature-empty">Select a headline to inspect it.<br>Save the story and your trading notes here.</div>';return;}
 const saved=newsBookmarks.find(b=>b.url===a.url);
 host.innerHTML='<div class="terminal-panel-head">READING DESK</div><div style="padding:20px"><div class="terminal-eyebrow">'+hx(a.source)+'</div><h3>'+hx(a.title)+'</h3><p class="feature-summary">'+terminalDate(a.published)+' · '+terminalTime(a.published)+' IST</p><div class="terminal-tags">'+a.tags.map(t=>'<span>'+hx(t)+'</span>').join('')+'</div><a class="btn" href="'+hx(safeWebUrl(a.url))+'" target="_blank" rel="noopener noreferrer">Read original article ↗</a><p class="feature-summary" style="margin-top:18px">Publisher articles open at the source. Save your own preparation and interpretation below.</p><label class="feature-summary" for="headlineNotes">My trading notes</label><textarea id="headlineNotes" maxlength="10000" placeholder="Why does this matter to my trade?">'+hx(terminalDrafts.get(a.id)??saved?.notes??'')+'</textarea><button class="btn ghost" id="saveHeadlineNotes">Save story & notes</button></div>';
 document.getElementById('headlineNotes').oninput=e=>terminalDrafts.set(a.id,e.target.value);
 document.getElementById('saveHeadlineNotes').onclick=async e=>{e.target.disabled=true;await saveHeadline(a,document.getElementById('headlineNotes').value);renderHeadlineStream();};
}
let econRange='This Week',econAnchor=null,econQuery='',econCurrency='',econImpact='',econExpanded=new Set();
function econDateKey(date){return new Date(date).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'});}
function econRangeBounds(range=econRange,anchor=econAnchor){const today=econDateKey(new Date()),d=new Date((anchor||today)+'T00:00:00Z');let start=new Date(d),end=new Date(d);if(range.includes('Week')){const shift=(d.getUTCDay()+6)%7;start.setUTCDate(d.getUTCDate()-shift);end=new Date(start);end.setUTCDate(start.getUTCDate()+6);}else if(range.includes('Month')){start.setUTCDate(1);end=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0));}return [start.toISOString().slice(0,10),end.toISOString().slice(0,10)];}
function econPreset(label){econRange=label;const d=new Date(econDateKey(new Date())+'T00:00:00Z');if(label==='Yesterday')d.setUTCDate(d.getUTCDate()-1);if(label==='Tomorrow')d.setUTCDate(d.getUTCDate()+1);if(label==='Last Week')d.setUTCDate(d.getUTCDate()-7);if(label==='Next Week')d.setUTCDate(d.getUTCDate()+7);if(label==='Last Month')d.setUTCMonth(d.getUTCMonth()-1,1);if(label==='Next Month')d.setUTCMonth(d.getUTCMonth()+1,1);econAnchor=d.toISOString().slice(0,10);renderNewsBody();}
function econShift(direction){const [start]=econRangeBounds(),d=new Date(start+'T00:00:00Z');if(econRange.includes('Month'))d.setUTCMonth(d.getUTCMonth()+direction);else d.setUTCDate(d.getUTCDate()+direction*(econRange.includes('Week')?7:1));econAnchor=d.toISOString().slice(0,10);renderNewsBody();}
function econFlag(currency){return {USD:'🇺🇸',EUR:'🇪🇺',GBP:'🇬🇧',JPY:'🇯🇵',AUD:'🇦🇺',CAD:'🇨🇦',CHF:'🇨🇭',NZD:'🇳🇿',CNY:'🇨🇳',ALL:'🌐'}[currency]||'🌐';}
function renderTerminalCalendar(main){
 const data=terminalCache.get('calendar')?.data,[start,end]=econRangeBounds();
 main.innerHTML='<div class="terminal-view-heading"><div><div class="terminal-eyebrow">FUNDAMENTALS / ECONOMIC RELEASES</div><h3>Economic Calendar</h3><p class="feature-summary">Scheduled releases and consensus figures · Times in Asia/Kolkata (IST).</p></div><button class="btn ghost" onclick="editNewsEvent()">+ Track an event</button></div><div class="econ-controls"><button class="btn ghost" aria-label="Previous period" onclick="econShift(-1)">‹</button><strong>'+hx(econRange)+': '+terminalDate(start)+' – '+terminalDate(end)+'</strong><button class="btn ghost" aria-label="Next period" onclick="econShift(1)">›</button><button class="btn ghost" id="econUpNext">▶ Up next</button><input id="econSearch" aria-label="Search calendar events" placeholder="Search events…" value="'+hx(econQuery)+'"><button class="btn ghost" id="econFilterToggle" aria-expanded="false">☷ Filter</button></div><nav class="econ-presets" aria-label="Calendar date ranges">'+['Yesterday','Today','Tomorrow','Last Week','This Week','Next Week','Last Month','This Month','Next Month'].map(label=>'<button class="'+(econRange===label?'selected':'')+'" onclick="econPreset(\''+label+'\')">'+label+'</button>').join('')+'</nav><div id="econFilters" class="feature-toolbar" hidden><label>Currency <select id="econCurrency"><option value="">All currencies</option>'+newsOptions(['USD','EUR','GBP','JPY','AUD','CAD','CHF','NZD','CNY','ALL'],econCurrency)+'</select></label><label>Impact <select id="econImpact"><option value="">All impacts</option>'+newsOptions(['High','Medium','Low','Holiday'],econImpact)+'</select></label><button class="btn ghost" id="econClear">Reset filters</button></div>'+terminalError('calendar')+'<div class="terminal-notice">'+hx(data?.coverage||'Loading weekly calendar…')+' Actuals absent from the export are shown as unavailable, not as pending results. <button class="terminal-text-button" id="econProviderToggle">View released figures in TradingView ↗</button></div><div class="terminal-panel terminal-table-wrap" id="econTable"></div><div id="econProvider" hidden></div><p class="feature-summary">Source: <a href="https://www.forexfactory.com/calendar" target="_blank" rel="noopener">Forex Factory / Fair Economy weekly export ↗</a> · Feed cached for 30 minutes · '+(data?'Checked '+terminalDate(data.fetchedAt)+' '+terminalTime(data.fetchedAt)+' IST':'Connecting…')+'. Consensus and schedules may change. Green/red actuals indicate numeric above/below consensus, not a trading signal.</p>';
 const search=document.getElementById('econSearch');search.oninput=()=>{econQuery=search.value;renderEconRows();};document.getElementById('econFilterToggle').onclick=e=>{const panel=document.getElementById('econFilters');panel.hidden=!panel.hidden;e.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));};for(const [id,set] of [['econCurrency',v=>econCurrency=v],['econImpact',v=>econImpact=v]])document.getElementById(id).onchange=e=>{set(e.target.value);renderEconRows();};document.getElementById('econClear').onclick=()=>{econCurrency='';econImpact='';econQuery='';renderNewsBody();};document.getElementById('econUpNext').onclick=()=>{econPreset('Today');document.querySelector('.econ-next')?.scrollIntoView({behavior:'smooth',block:'center'});};document.getElementById('econProviderToggle').onclick=()=>{const host=document.getElementById('econProvider');host.hidden=!host.hidden;if(!host.hidden&&!host.children.length){host.innerHTML=widgetShell('econReleasedWidget','https://www.tradingview.com/economic-calendar/','Economic calendar');terminalWidget('econReleasedWidget','events',{countryFilter:'us,gb,eu,jp,au,ca,ch,nz,in,cn',importanceFilter:'0,1',height:600});}};renderEconRows();
}
function renderEconRows(){
 const host=document.getElementById('econTable');if(!host)return;const data=terminalCache.get('calendar')?.data,[start,end]=econRangeBounds(),today=econDateKey(new Date()),items=(data?.items||[]).filter(e=>{const day=econDateKey(e.date);return day>=start&&day<=end&&(!econCurrency||e.currency===econCurrency)&&(!econImpact||e.impact===econImpact)&&e.title.toLowerCase().includes(econQuery.toLowerCase());}),next=items.find(e=>Date.parse(e.date)>=Date.now());let day='';
 host.innerHTML='<table class="terminal-table econ-table"><thead><tr><th>DATE</th><th>TIME · IST</th><th>CURRENCY</th><th>IMPACT</th><th>EVENT</th><th>ACTUAL</th><th>EXPECTED</th><th>PREVIOUS</th></tr></thead><tbody>'+items.map(e=>{const key=econDateKey(e.date),newDay=day!==key;day=key;const future=Date.parse(e.date)>Date.now(),isNext=e===next,expanded=econExpanded.has(e.id),actual=e.actual??(future?'Pending':'Unavailable');let color='';if(e.actual!==null&&e.forecast!==null&&/^[-+]?\d+(\.\d+)?%?$/.test(e.actual)&&/^[-+]?\d+(\.\d+)?%?$/.test(e.forecast))color=parseFloat(e.actual)>parseFloat(e.forecast)?'pos':parseFloat(e.actual)<parseFloat(e.forecast)?'neg':'';return (isNext?'<tr class="econ-up-next"><td colspan="8">UP NEXT · <span data-countdown="'+hx(e.date)+'">'+countdownLabel(e.date)+'</span></td></tr>':'')+'<tr class="'+(key===today?'econ-today ':'')+(isNext?'econ-next ':'')+(newDay?'econ-day-start':'')+'"><td>'+(newDay?'<strong>'+new Date(e.date).toLocaleDateString('en-GB',{timeZone:'Asia/Kolkata',weekday:'short'})+'</strong><small>'+terminalDate(e.date)+'</small>':'')+'</td><td>'+ (e.impact==='Holiday'?'All day':terminalTime(e.date))+'</td><td>'+econFlag(e.currency)+' '+hx(e.currency)+'</td><td><span class="econ-impact '+e.impact.toLowerCase()+'" title="'+e.impact+' impact" aria-label="'+e.impact+' impact">▂▅▇</span></td><td><button class="econ-event" data-econ-id="'+hx(e.id)+'" aria-expanded="'+expanded+'">'+hx(e.title)+' <span>'+(expanded?'⌃':'⌄')+'</span></button></td><td class="'+color+'">'+hx(actual)+'</td><td>'+hx(e.forecast??'—')+'</td><td>'+hx(e.previous??'—')+'</td></tr>'+(expanded?'<tr class="econ-details"><td colspan="8"><div><strong>'+hx(e.title)+'</strong><p>Source: '+hx(e.source)+' · '+terminalDate(e.date)+' '+terminalTime(e.date)+' IST</p><p>Actual: '+hx(actual)+' · Expected: '+hx(e.forecast??'Not supplied')+' · Previous: '+hx(e.previous??'Not supplied')+'</p><p>Historical graphs and AI anticipation require additional data and are not generated from the schedule.</p><a class="terminal-text-button" href="'+hx(e.url)+'" target="_blank" rel="noopener">Open source calendar ↗</a> <button class="btn ghost" onclick="editNewsEvent()">+ Add preparation notes</button></div></td></tr>':'');}).join('')+(!items.length?'<tr><td colspan="8" class="feature-empty">'+(data?'No events in this selection. The current feed covers its published week only; broader history and future periods need a full calendar data provider.':'Loading calendar feed…')+'</td></tr>':'')+'</tbody></table>';
 host.querySelectorAll('[data-econ-id]').forEach(b=>b.onclick=()=>{const id=b.dataset.econId;if(econExpanded.has(id))econExpanded.delete(id);else econExpanded.add(id);renderEconRows();});
}

function terminalChart(points,label,color='var(--accent)',format=terminalNumber){
 const valid=points.filter(p=>Number.isFinite(p.value));if(!valid.length)return'<div class="feature-empty">No history available.</div>';
 const w=900,h=240,pad=44,min=Math.min(...valid.map(p=>p.value)),max=Math.max(...valid.map(p=>p.value)),span=max-min||1,x=i=>pad+i*(w-2*pad)/Math.max(1,valid.length-1),y=v=>h-pad-(v-min)/span*(h-2*pad);
 const path=valid.map((p,i)=>(i?'L':'M')+x(i).toFixed(1)+','+y(p.value).toFixed(1)).join(' ');
 const ticks=[min,(min+max)/2,max].map(v=>'<line x1="'+pad+'" x2="'+(w-pad)+'" y1="'+y(v)+'" y2="'+y(v)+'" stroke="var(--border)"/><text x="'+pad+'" y="'+(y(v)-7)+'" fill="var(--text-low)" font-size="11">'+hx(format(v))+'</text>').join('');
 return '<svg class="terminal-chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="'+hx(label)+'"><title>'+hx(label)+'</title>'+ticks+'<path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="2.5"/>'+valid.map((p,i)=>'<circle cx="'+x(i)+'" cy="'+y(p.value)+'" r="4" fill="transparent"><title>'+hx(p.date+': '+format(p.value))+'</title></circle>').join('')+'<text x="'+pad+'" y="'+(h-10)+'" font-size="11" fill="var(--text-low)">'+hx(terminalDate(valid[0].date))+'</text><text text-anchor="end" x="'+(w-pad)+'" y="'+(h-10)+'" font-size="11" fill="var(--text-low)">'+hx(terminalDate(valid.at(-1).date))+'</text></svg>';
}
function renderTerminalCot(main){
 const data=terminalCache.get('cot')?.data,detail=terminalCache.get('cot:'+cotMarket)?.data,market=data?.markets.find(m=>m.id===cotMarket),history=(detail?.history||[]).slice(0,cotRange).reverse(),current=history.at(-1),nets=(detail?.history||[]).slice(0,156).map(r=>r.net).filter(Number.isFinite),index=current&&nets.length>1&&Math.max(...nets)!==Math.min(...nets)?(current.net-Math.min(...nets))/(Math.max(...nets)-Math.min(...nets))*100:null;
 main.innerHTML='<div class="terminal-view-heading"><div><h3>COT Report</h3><p class="feature-summary">Managed money for metals and oil · Leveraged funds for currencies and Bitcoin · Futures only.</p></div><select id="cotMarket" aria-label="COT market">'+(data?.markets||[{id:'gold',name:'Gold'}]).map(m=>'<option value="'+m.id+'" '+(m.id===cotMarket?'selected':'')+'>'+hx(m.name)+'</option>').join('')+'</select></div>'+terminalError('cot')+'<div class="terminal-panel terminal-table-wrap"><table class="terminal-table"><thead><tr><th>MARKET</th><th>AS OF</th><th>NET</th><th>WEEK Δ</th><th>LONG / SHORT</th><th>OPEN INTEREST</th></tr></thead><tbody>'+(data?.markets||[]).map(m=>'<tr data-market="'+m.id+'" class="'+(m.id===cotMarket?'selected':'')+'"><td><button>'+hx(m.name)+'</button></td><td>'+terminalDate(m.date)+'</td><td class="'+(m.net>=0?'pos':'neg')+'">'+signedNumber(m.net)+'</td><td>'+signedNumber(m.change)+'</td><td>'+longShortBar(m.long,m.short)+'</td><td>'+terminalNumber(m.openInterest)+'</td></tr>').join('')+'</tbody></table>'+(!data?terminalEmpty('cot'):'')+'</div><div class="terminal-view-heading" style="margin-top:22px"><h3>'+hx(market?.name||detail?.market?.name||'Gold')+' · positioning history</h3><div class="feature-toolbar" id="cotRanges">'+[[26,'6M'],[52,'1Y'],[104,'2Y'],[156,'3Y']].map(([n,label])=>'<button class="btn ghost '+(cotRange===n?'selected':'')+'" data-range="'+n+'">'+label+'</button>').join('')+'</div></div>'+terminalError('cot:'+cotMarket)+(detail?.errors?.length?'<div class="terminal-notice">Some CFTC report data is unavailable. Available reports are shown below.</div>':'')+(detail?'<div class="terminal-kpis">'+terminalKpi('SPECULATOR NET',signedNumber(current?.net),current?.groups[0]?.name||'')+terminalKpi('WEEKLY CHANGE',signedNumber(current?.change),current?.date?terminalDate(current.date):'')+terminalKpi('COT INDEX',index===null?'—':index.toFixed(0)+' / 100',nets.length+' weekly reports in lookback')+terminalKpi('OPEN INTEREST',terminalNumber(current?.openInterest),'Futures contracts')+'</div>'+terminalPanel('SPECULATOR NET · CONTRACTS',terminalChart(history.map(r=>({date:r.date,value:r.net})),'Net speculative futures positions'))+terminalPanel('PARTICIPANTS · '+terminalDate(current?.date),cotGroupsTable(current?.groups||[]))+terminalPanel('LEGACY NET · COMMERCIALS',terminalChart((detail.legacy||[]).slice(0,cotRange).reverse().map(r=>({date:r.date,value:r.groups.find(g=>g.name==='Commercials')?.net})),'Legacy commercial net positions','var(--gold)'))+terminalPanel('OPEN INTEREST',terminalChart(history.map(r=>({date:r.date,value:r.openInterest})),'Open interest','var(--profit)')):'<div class="feature-empty">Loading weekly history…</div>')+'<p class="feature-summary">Source: <a href="https://www.cftc.gov/MarketReports/CommitmentsofTraders/index.htm" target="_blank" rel="noopener noreferrer">CFTC Commitments of Traders</a>. Usually released Friday for Tuesday positions. COT index is net position within the available 156-report high/low range. Currency futures are the foreign currency against USD; long JPY corresponds to short USD/JPY. Stale/missing report dates are shown explicitly.</p>';
 document.getElementById('cotMarket').onchange=e=>selectCotMarket(e.target.value);main.querySelectorAll('[data-market]').forEach(row=>row.querySelector('button').onclick=()=>selectCotMarket(row.dataset.market));main.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{cotRange=Number(b.dataset.range);renderNewsBody();});
}
async function selectCotMarket(id){cotMarket=id;renderNewsBody();await terminalFetch('cot',id);if(newsView==='cot')renderNewsBody();}
function longShortBar(long,short){const total=(long||0)+(short||0);if(!total)return'—';const pct=long/total*100;return '<div class="terminal-position-bar" title="Long '+terminalNumber(long)+' / Short '+terminalNumber(short)+'"><span style="width:'+pct.toFixed(2)+'%"></span></div><small>'+pct.toFixed(0)+'% long</small>';}
function cotGroupsTable(groups){return '<div class="terminal-table-wrap"><table class="terminal-table"><thead><tr><th>GROUP</th><th>LONG</th><th>SHORT</th><th>NET</th><th>LONG / SHORT</th></tr></thead><tbody>'+groups.map(g=>'<tr><td>'+hx(g.name)+'</td><td>'+terminalNumber(g.long)+'</td><td>'+terminalNumber(g.short)+'</td><td class="'+(g.net>=0?'pos':'neg')+'">'+signedNumber(g.net)+'</td><td>'+longShortBar(g.long,g.short)+'</td></tr>').join('')+'</tbody></table></div>';}
function fedOutcomeColor(o){return o.move<0?'var(--profit)':o.move>0?'var(--loss)':'var(--text-low)';}
function fedOddsBars(meeting){return '<div class="fed-odds">'+meeting.outcomes.map(o=>'<div><span>'+hx(o.label)+'</span><strong>'+(o.probability===null?'—':o.probability.toFixed(1)+'%')+'<small class="fed-delta '+(o.change>=0?'pos':'neg')+'">'+(Number.isFinite(o.change)?(o.change>0?'+':'')+o.change.toFixed(1)+'pp':'—')+'</small></strong><div><i style="background:'+fedOutcomeColor(o)+';width:'+Math.max(0,Math.min(100,o.probability||0))+'%"></i></div></div>').join('')+'</div>';}
function fedRatePath(data){let value=data.rate?(data.rate.targetRateFrom+data.rate.targetRateTo)/2:null;return data.meetings.map(m=>{const change=m.outcomes.length&&m.outcomes.every(o=>Number.isFinite(o.probability)&&Number.isFinite(o.move))?m.outcomes.reduce((n,o)=>n+o.probability*o.move/10000,0):null;value=value!==null&&change!==null?value+change:null;return {date:m.date,value,change};});}
function fedDetailedChart(data,points){
 const now=data.rate?(data.rate.targetRateFrom+data.rate.targetRateTo)/2:null,all=[{date:new Date().toISOString(),value:now},...points],valid=all.filter(p=>Number.isFinite(p.value));if(!valid.length)return '<div class="feature-empty">Rate path unavailable.</div>';
 const w=1100,h=300,pad=55,low=Math.min(...valid.map(p=>p.value),data.rate?.targetRateFrom??Infinity)-.1,high=Math.max(...valid.map(p=>p.value),data.rate?.targetRateTo??-Infinity)+.1,x=i=>pad+i*(w-2*pad)/Math.max(1,all.length-1),y=v=>h-pad-(v-low)/(high-low)*(h-2*pad);
 let body='';if(data.rate)body+='<rect x="'+pad+'" width="'+(w-2*pad)+'" y="'+y(data.rate.targetRateTo)+'" height="'+(y(data.rate.targetRateFrom)-y(data.rate.targetRateTo))+'" fill="var(--accent-dim)"/>';
 for(let i=0;i<4;i++){const v=low+(high-low)*i/3;body+='<line x1="'+pad+'" x2="'+(w-pad)+'" y1="'+y(v)+'" y2="'+y(v)+'" stroke="var(--border)"/><text x="8" y="'+(y(v)+4)+'" fill="var(--text-mid)" font-size="11">'+v.toFixed(2)+'%</text>';}
 let path='';all.forEach((p,i)=>{if(!Number.isFinite(p.value))return;path+=(path?'L':'M')+x(i)+','+y(p.value)+' ';body+='<circle cx="'+x(i)+'" cy="'+y(p.value)+'" r="4" fill="var(--accent)"><title>'+hx((i?terminalDate(p.date):'Now')+': '+p.value.toFixed(2)+'%')+'</title></circle><text text-anchor="middle" x="'+x(i)+'" y="'+(h-20)+'" fill="var(--text-mid)" font-size="10">'+hx(i?new Date(p.date).toLocaleDateString('en-GB',{timeZone:'America/New_York',month:'short',year:'2-digit'}):'Now')+'</text>';});
 return '<svg class="terminal-chart" role="img" aria-label="Implied rate path with current target range shaded" viewBox="0 0 '+w+' '+h+'">'+body+'<path d="'+path+'" fill="none" stroke="var(--accent)" stroke-width="2.5"/></svg><p class="feature-summary" style="padding:0 20px 16px">Current midpoint plus each meeting’s probability-weighted move · shaded band: today’s target range · Dates use New York meeting dates.</p>';
}
function renderTerminalFed(main){
 const data=terminalCache.get('fed')?.data;if(!data){main.innerHTML=terminalEmpty('fed');return;}const rate=data.rate,next=data.meetings[0],points=fedRatePath(data),last=points.filter(p=>Number.isFinite(p.value)).at(-1),top=next?.outcomes.filter(o=>Number.isFinite(o.probability)).sort((a,b)=>b.probability-a.probability)[0],labels=[...new Set(data.meetings.flatMap(m=>m.outcomes.map(o=>o.label)))];
 const meetingDate=d=>new Date(d).toLocaleDateString('en-GB',{timeZone:'America/New_York',day:'numeric',month:'short',year:'numeric'});
 main.innerHTML='<div class="terminal-view-heading"><div><div class="terminal-eyebrow">FUNDAMENTALS / FEDERAL RESERVE</div><h3>Fed Watch</h3><p class="feature-summary">'+(top?'Markets price '+hx(top.label)+' at '+top.probability.toFixed(1)+'% for '+meetingDate(next.date)+'. ':'')+'Kalshi contract pricing · Checked '+terminalTime(data.fetchedAt)+' IST.</p></div></div>'+terminalError('fed')+(data.errors.length?'<p class="terminal-notice">Some sources are unavailable. Source dates identify the available data.</p>':'')+'<div class="fed-detail-layout">'+terminalPanel('POLICY RATE','<div class="macro-card"><div class="terminal-eyebrow">TARGET RANGE</div><div class="fed-policy-value">'+(rate?rate.targetRateFrom.toFixed(2)+'–'+rate.targetRateTo.toFixed(2)+'%':'—')+'</div><div class="fed-policy-meta"><div><small>EFFECTIVE · EFFR</small><strong>'+(rate?rate.percentRate.toFixed(2)+'%':'—')+'</strong></div><div><small>AS OF</small><strong>'+terminalDate(rate?.effectiveDate)+'</strong></div></div><p class="feature-summary">'+(last?'Priced for '+last.value.toFixed(2)+'% after '+meetingDate(last.date)+'.':'Rate path unavailable.')+'</p></div>')+terminalPanel('NEXT MEETING'+(next?' · '+meetingDate(next.date):''),next?'<div class="macro-card"><p class="feature-summary" data-countdown="'+hx(next.date)+'">'+countdownLabel(next.date)+'</p>'+fedOddsBars(next)+'<p class="feature-summary" style="margin-top:14px">Δ shows raw contract-price percentage-point change from previous price; bar probabilities are normalized per meeting.</p><button class="terminal-text-button" onclick="newsView=\'calendar\';renderNews()">FOMC on the calendar →</button></div>':'<div class="feature-empty">Decision markets unavailable.</div>')+'</div>'+terminalPanel('IMPLIED RATE PATH',fedDetailedChart(data,points))+terminalPanel('EVERY MEETING · NEW YORK DATES','<div class="terminal-table-wrap"><table class="terminal-table"><thead><tr><th>MEETING</th>'+labels.map(l=>'<th>'+hx(l)+'</th>').join('')+'<th>LIKELIEST</th><th>IMPLIED RATE</th></tr></thead><tbody>'+data.meetings.map((m,i)=>{const best=m.outcomes.filter(o=>Number.isFinite(o.probability)).sort((a,b)=>b.probability-a.probability)[0];return '<tr><td>'+meetingDate(m.date)+'</td>'+labels.map(l=>{const o=m.outcomes.find(o=>o.label===l);return '<td class="fed-cell '+(o===best?'fed-likely':'')+'" style="background:'+(o&&Number.isFinite(o.probability)?'color-mix(in srgb,'+fedOutcomeColor(o)+' '+Math.max(0,o.probability*.35)+'%, transparent)':'transparent')+'">'+(Number.isFinite(o?.probability)?o.probability.toFixed(1)+'%':'—')+'</td>';}).join('')+'<td>'+hx(best?.label||'—')+'</td><td>'+(Number.isFinite(points[i].value)?points[i].value.toFixed(2)+'% <small>'+signedNumber(points[i].change*100)+'bp</small>':'—')+'</td></tr>';}).join('')+'</tbody></table></div>')+terminalPanel('EFFECTIVE FED FUNDS · RECENT HISTORY',terminalChart((data.rates||[]).slice().reverse().map(r=>({date:r.effectiveDate,value:r.percentRate})),'Effective federal funds history','var(--gold)',v=>v.toFixed(2)+'%'))+'<p class="feature-summary">Official rates: <a href="https://www.newyorkfed.org/markets/reference-rates/effr" target="_blank" rel="noopener">NY Fed</a>. Probabilities: <a href="https://kalshi.com/markets/kxfeddecision" target="_blank" rel="noopener">Kalshi</a> bid/ask midpoints normalized to 100%, distinct from CME FedWatch. >25bp buckets approximate 50bp for the expected path. Pricing is not a forecast guarantee.</p>';
}

setInterval(()=>{if(!terminalPaused && document.getElementById('news')?.classList.contains('active'))refreshNewsTerminal(true);},60000);

function macroValue(value,unit='%'){return Number.isFinite(value)?(unit==='K'?(value>0?'+':'')+terminalNumber(value)+'K':value.toFixed(2)+unit):'—';}
function macroScheduleNotice(data){return data&&!data.scheduleLive?'<p class="terminal-notice">Live BLS schedule unavailable. Showing the official schedule verified '+hx(data.scheduleVerified)+'. Dates may change; <a href="'+hx(data.scheduleSource)+'" target="_blank" rel="noopener noreferrer">check BLS ↗</a>.</p>':'';}
function macroReleaseCard(kind){const data=terminalCache.get(kind)?.data,next=data?.schedule?.[0],last=data?.history?.[0];return terminalPanel('USA · '+kind.toUpperCase(),'<div class="macro-card"><span class="news-impact high">HIGH IMPACT · USD</span><h3>'+ (kind==='cpi'?'Consumer Price Index':'Nonfarm Payrolls')+'</h3><strong>'+(next?terminalDate(next.date)+' · '+terminalTime(next.date)+' IST':'Schedule unavailable')+'</strong><p class="feature-summary">'+(next?countdownLabel(next.date):'Check the official BLS schedule')+'</p><p>Latest: '+(kind==='cpi'?macroValue(last?.mom)+' MoM':macroValue(last?.payrolls,'K')+' jobs')+' <small>'+(last?terminalDate(last.date).slice(3):'')+'</small></p>'+macroScheduleNotice(data)+'<button class="terminal-text-button" data-go="'+kind+'">Open '+kind.toUpperCase()+' monitor →</button></div>');}
function terminalSessions(now=new Date()){
 return [['Sydney','Australia/Sydney',8,17],['Tokyo','Asia/Tokyo',9,18],['London','Europe/London',8,17],['New York','America/New_York',8,17]].map(([name,zone,start,end])=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:zone,weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).map(p=>[p.type,p.value]));return {name,time:parts.hour+':'+parts.minute,open:!['Sat','Sun'].includes(parts.weekday)&&Number(parts.hour)>=start&&Number(parts.hour)<end};});
}
function terminalWidget(id,type,options){const host=document.getElementById(id);if(!host||host.querySelector('script,iframe'))return;const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-'+type+'.js';script.async=true;script.textContent=JSON.stringify({colorTheme:currentTvTheme(),isTransparent:true,locale:'en',width:'100%',...options});host.append(script);}
function widgetShell(id,url,label){return '<div id="'+id+'" class="tradingview-widget-container dashboard-widget"><div class="tradingview-widget-container__widget"></div><a class="feature-summary" href="'+url+'" target="_blank" rel="noopener nofollow">'+label+' by TradingView ↗</a></div>';}
function renderTerminalMacro(main,kind){
 const data=terminalCache.get(kind)?.data,cpi=kind==='cpi',rows=data?.history||[],latest=rows[0],previous=rows[1],next=data?.schedule?.[0];
 const columns=cpi?[['mom','Headline MoM','%'],['yoy','Headline YoY','%'],['coreMom','Core MoM','%'],['coreYoy','Core YoY','%']]:[['payrolls','Payroll change','K'],['unemployment','Unemployment','%'],['wages','Hourly earnings MoM','%']];
 const headlines=(terminalCache.get('headlines')?.data?.items||[]).filter(a=>a.tags.includes(cpi?'Inflation':'Jobs')).slice(0,6);
 main.innerHTML='<div class="terminal-view-heading"><div><div class="terminal-eyebrow">UNITED STATES / HIGH IMPACT / USD</div><h3>'+ (cpi?'CPI · Inflation Monitor':'NFP · Employment Monitor')+'</h3><p class="feature-summary">'+(cpi?'Headline and core consumer prices. Monthly changes use seasonally adjusted indexes; annual changes use unadjusted indexes.':'Total nonfarm payrolls, unemployment and average hourly earnings. Seasonally adjusted; payroll changes are in thousands.')+'</p></div><a class="btn ghost" href="https://www.bls.gov/news.release/'+(cpi?'cpi':'empsit')+'.htm" target="_blank" rel="noopener noreferrer">Official release ↗</a></div>'+terminalError(kind)+(data?.errors.length?'<p class="terminal-notice">Some BLS series are unavailable; missing values are shown as —.</p>':'')+'<div class="terminal-kpis">'+columns.map(([key,label,unit])=>terminalKpi(label.toUpperCase(),macroValue(latest?.[key],unit),latest?'Reference month: '+terminalDate(latest.date).slice(3)+' · Previous '+macroValue(previous?.[key],unit):'Awaiting BLS data')).join('')+'</div><div class="terminal-dashboard-grid">'+macroReleaseCard(kind)+terminalPanel('RELEASE CONTEXT','<div class="macro-card"><h3>'+(next?terminalDate(next.date):'Next release unavailable')+'</h3><p>Actual: <strong>Pending release</strong> · Consensus forecast: <strong>Not supplied by BLS</strong></p><p class="feature-summary">Latest published values above describe their labelled reference month, not the upcoming release. Historical values reflect current revisions and may differ from the initial release.</p><button class="btn ghost" data-go="calendar">View calendar & consensus</button><button class="btn ghost" onclick="editNewsEvent()">+ Add preparation notes</button></div>')+'</div>'+macroScheduleNotice(data)+'<div class="terminal-dashboard-grid">'+columns.slice(0,2).map(([key,label,unit])=>terminalPanel(label.toUpperCase()+' · HISTORY',terminalChart(rows.slice().reverse().map(r=>({date:r.date,value:r[key]})),label,'var(--accent)',v=>macroValue(v,unit)))).join('')+'</div>'+terminalPanel('RELEASE HISTORY · LATEST REVISED DATA','<div class="terminal-table-wrap"><table class="terminal-table"><thead><tr><th>REFERENCE MONTH</th>'+columns.map(c=>'<th>'+hx(c[1])+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+terminalDate(r.date).slice(3)+'</td>'+columns.map(([key,,unit])=>'<td>'+macroValue(r[key],unit)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>')+'<div class="terminal-dashboard-grid">'+terminalPanel('UPCOMING RELEASES · IST','<div class="macro-card">'+(data?.schedule||[]).slice(0,6).map(r=>'<p>'+terminalDate(r.date)+' · '+terminalTime(r.date)+' IST</p>').join('')+'</div>')+terminalPanel('RELATED '+(cpi?'INFLATION':'EMPLOYMENT')+' HEADLINES',headlines.length?headlines.map(a=>headlineRow(a,true)).join(''):'<div class="feature-empty">No related headlines in the current feeds.</div>')+'</div><p class="feature-summary">Source: U.S. Bureau of Labor Statistics public API. BLS data refreshes hourly and may arrive after release time. '+(data?'Last checked '+terminalDate(data.fetchedAt)+' '+terminalTime(data.fetchedAt)+' IST.':'')+'</p>';
 main.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{newsView=b.dataset.go;renderNews();});bindHeadlineRows(main);
}
function sessionTimeline(now=new Date()){
 const zones=[['Sydney','Australia/Sydney',8,17],['Tokyo','Asia/Tokyo',9,18],['London','Europe/London',8,17],['New York','America/New_York',8,17]],sessions=terminalSessions(now),istParts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).map(p=>[p.type,p.value])),marker=(Number(istParts.hour)*60+Number(istParts.minute))/14.4;
 return '<div class="session-timeline">'+zones.map(([name,zone,start,end],i)=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now).map(p=>[p.type,p.value])),local=Number(parts.hour)*60+Number(parts.minute),ist=Number(istParts.hour)*60+Number(istParts.minute),begin=((start*60+ist-local)%1440+1440)%1440,duration=(end-start)*60,segments=begin+duration<=1440?[[begin,duration]]:[[begin,1440-begin],[0,begin+duration-1440]];return '<div class="session-track-row '+(sessions[i].open?'is-open':'')+'"><strong>'+name+'</strong><span>'+sessions[i].time+'</span><div class="session-track">'+segments.map(([a,b])=>'<i style="left:'+a/14.4+'%;width:'+b/14.4+'%"></i>').join('')+'<b style="left:'+marker+'%"></b></div></div>';}).join('')+'<div class="session-axis">'+['00','03','06','09','12','15','18','21','00'].map(s=>'<span>'+s+'</span>').join('')+'</div><p class="feature-summary" style="margin-top:18px">Session windows in IST · Local clocks adjust for DST · Indicative weekday hours; exchange holidays excluded.</p></div>';
}
setInterval(()=>{if(!document.getElementById('news')?.classList.contains('active'))return;document.querySelectorAll('[data-countdown]').forEach(el=>el.textContent=countdownLabel(el.dataset.countdown));const timeline=document.getElementById('sessionTimeline');if(timeline)timeline.innerHTML=sessionTimeline();},1000);
